import static org.junit.Assert.assertNotNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.when;

public class BasicDeserializerFactory_createTreeDeserializer_TriageGen1Test {

    private BasicDeserializerFactory factory;
    private DeserializationConfig config;
    private JavaType javaType;
    private BeanDescription beanDesc;

    @Before
    public void setUp() {
        // DeserializerFactoryConfig is required for constructor
        DeserializerFactoryConfig factoryConfig = Mockito.mock(DeserializerFactoryConfig.class);
        factory = spy(new BasicDeserializerFactory(factoryConfig) {});
        config = Mockito.mock(DeserializationConfig.class);
        javaType = Mockito.mock(JavaType.class);
        beanDesc = Mockito.mock(BeanDescription.class);
    }

    /**
     * Tests the scenario where a custom deserializer is found via _findCustomTreeNodeDeserializer.
     * This covers the 'if (custom != null)' branch.
     */
    @Test
    public void testCreateTreeDeserializer_WithCustomDeserializer() throws JsonMappingException {
        // Arrange
        Class<? extends JsonNode> nodeClass = ObjectNode.class;
        when(javaType.getRawClass()).thenReturn(nodeClass);

        JsonDeserializer<?> customDeserializer = Mockito.mock(JsonDeserializer.class);

        // Mock the protected method _findCustomTreeNodeDeserializer
        doReturn(customDeserializer).when(factory)
                ._findCustomTreeNodeDeserializer(eq(nodeClass), eq(config), eq(beanDesc));

        // Act
        JsonDeserializer<?> result = factory.createTreeDeserializer(config, javaType, beanDesc);

        // Assert
        assertNotNull(result);
        assertEquals(customDeserializer, result);
    }

    /**
     * Tests the scenario where no custom deserializer is found.
     * This covers the 'return JsonNodeDeserializer.getDeserializer(nodeClass)' branch.
     */
    @Test
    public void testCreateTreeDeserializer_WithDefaultDeserializer() throws JsonMappingException {
        // Arrange
        Class<? extends JsonNode> nodeClass = ObjectNode.class;
        when(javaType.getRawClass()).thenReturn(nodeClass);

        // Mock the protected method to return null (custom not found)
        doReturn(null).when(factory)
                ._findCustomTreeNodeDeserializer(eq(nodeClass), eq(config), eq(beanDesc));

        // Act
        JsonDeserializer<?> result = factory.createTreeDeserializer(config, javaType, beanDesc);

        // Assert
        assertNotNull(result);
        // JsonNodeDeserializer.getDeserializer(ObjectNode.class) returns a standard implementation
        // We check that it is indeed a deserializer for the requested class
        assertEquals(JsonNodeDeserializer.class, result.getClass());
    }

    /**
     * Tests the scenario where the internal call throws a JsonMappingException.
     * This ensures exception propagation is handled correctly.
     */
    @Test(expected = JsonMappingException.class)
    public void testCreateTreeDeserializer_ThrowsException() throws JsonMappingException {
        // Arrange
        Class<? extends JsonNode> nodeClass = ObjectNode.class;
        when(javaType.getRawClass()).thenReturn(nodeClass);

        doReturn(null).when(factory)
                ._findCustomTreeNodeDeserializer(eq(nodeClass), eq(config), eq(beanDesc));

        // Force the fallback call (JsonNodeDeserializer.getDeserializer) to fail or the logic to fail
        // Since we can't easily mock the static JsonNodeDeserializer, we mock the custom finder to throw
        doReturn(null).when(factory)._findCustomTreeNodeDeserializer(any(), any(), any());

        // We simulate an exception by triggering a runtime error during the process if possible, 
        // but here we'll just mock the custom finder to throw the expected exception.
        doReturn(null).when(factory)._findCustomTreeNodeDeserializer(any(), any(), any());

        // To trigger the exception path in the actual code logic:
        when(javaType.getRawClass()).thenThrow(new RuntimeException("Simulated Exception"));

        // Act
        factory.createTreeDeserializer(config, javaType, beanDesc);
    }
}
